import numpy as np
import time
from scipy.special import gammaln


def _R(h):
    h = np.asarray(h, dtype=float)
    L = np.convolve(h, h)
    L = np.concatenate(([0.0], L, [0.0]))
    s = L[:-1] ** 2 + L[:-1] * L[1:] + L[1:] ** 2
    l2sq = s.sum() / 3.0
    l1 = h.sum() ** 2
    linf = L.max()
    if l1 <= 0 or linf <= 0:
        return -1.0
    return l2sq / (l1 * linf)


def construct(budget_seconds, start):
    t0 = time.process_time()
    best_h = None
    best_r = -1.0

    if start is not None:
        s = np.asarray(start, dtype=float)
        if s.size > 0 and np.all(np.isfinite(s)) and s.sum() > 0:
            best_h = s.copy()
            best_r = _R(s)

    for n in (500, 1000, 2000):
        if time.process_time() - t0 > budget_seconds * 0.8:
            break
        i = np.arange(n + 1, dtype=float)
        logC = gammaln(n + 1) - gammaln(i + 1) - gammaln(n - i + 1)
        h = np.exp(logC - logC.max())
        r = _R(h)
        if r > best_r:
            best_r = r
            best_h = h

    if best_h is None:
        return np.ones(50)
    return best_h

import numpy as np
import time
from scipy.optimize import minimize


def _R_from_h(h):
    h = np.maximum(h, 0.0)
    m = h.max()
    if m <= 0:
        return 0.0
    h = h / m
    L = np.convolve(h, h)
    Lp = np.concatenate(([0.0], L, [0.0]))
    a = Lp[:-1]
    b = Lp[1:]
    l2sq = np.sum(a * a + a * b + b * b) / 3.0
    l1 = np.sum(h) ** 2
    linf = Lp.max()
    if linf <= 0 or l1 <= 0:
        return 0.0
    return l2sq / (l1 * linf)


def _R_and_grad(h):
    h = np.maximum(h, 0.0)
    N = h.size
    L = np.convolve(h, h)
    Lp = np.concatenate(([0.0], L, [0.0]))
    a = Lp[:-1]
    b = Lp[1:]
    A = np.sum(a * a + a * b + b * b) / 3.0
    S = np.sum(h)
    B = S * S
    C = Lp.max()
    if C <= 0 or B <= 0:
        return 0.0, np.zeros(N)
    R = A / (B * C)

    gL = (Lp[:-2] + 4.0 * Lp[1:-1] + Lp[2:]) / 3.0
    dA = 2.0 * np.correlate(gL, h, mode='valid')
    dB = 2.0 * S * np.ones(N)
    kstar = int(np.argmax(Lp))
    dC = np.zeros(N)
    m = kstar - 1
    if 0 <= m <= 2 * N - 2:
        for i in range(N):
            j = m - i
            if 0 <= j < N:
                dC[i] = 2.0 * h[j]

    invBC = 1.0 / (B * C)
    g = dA * invBC - (A / (B * B * C)) * dB - (A / (B * C * C)) * dC
    return R, g


def _neg_R_and_grad(x):
    R, g = _R_and_grad(x)
    return -R, -g


def _slsqp_round(h, deadline):
    h = np.maximum(h, 0.0)
    m = h.max()
    if m <= 0:
        return h, _R_from_h(h)
    h = h / m
    N = h.size
    L = np.convolve(h, h)
    Lp = np.concatenate(([0.0], L, [0.0]))
    C = Lp.max()
    if C <= 0:
        return h, _R_from_h(h)

    active = np.where(Lp >= 0.999 * C)[0]
    aset = set()
    for j in active:
        for k in (j - 1, j, j + 1):
            if 0 <= k < Lp.size:
                aset.add(int(k))
    aset = np.array(sorted(aset), dtype=int)

    def obj(x):
        hh = np.maximum(x, 0.0)
        LL = np.convolve(hh, hh)
        LLp = np.concatenate(([0.0], LL, [0.0]))
        a = LLp[:-1]
        b = LLp[1:]
        A = np.sum(a * a + a * b + b * b) / 3.0
        S = np.sum(hh)
        B = S * S
        Cm = LLp.max()
        if Cm <= 0 or B <= 0:
            return 1e10
        return -A / (B * Cm)

    def grad(x):
        _, g = _R_and_grad(x)
        return -g

    def con(x):
        hh = np.maximum(x, 0.0)
        LL = np.convolve(hh, hh)
        LLp = np.concatenate(([0.0], LL, [0.0]))
        return C * (1.0 + 1e-6) - LLp[aset]

    def con_jac(x):
        hh = np.maximum(x, 0.0)
        Nn = hh.size
        J = np.zeros((aset.size, Nn))
        for r, k in enumerate(aset):
            mm = k - 1
            if 0 <= mm <= 2 * Nn - 2:
                for i in range(Nn):
                    j = mm - i
                    if 0 <= j < Nn:
                        J[r, i] = -2.0 * hh[j]
        return J

    if time.process_time() > deadline:
        return h, _R_from_h(h)

    try:
        res = minimize(obj, h.copy(), jac=grad, method='SLSQP',
                       bounds=[(0.0, None)] * N,
                       constraints=[{'type': 'ineq', 'fun': con, 'jac': con_jac}],
                       options={'maxiter': 200, 'ftol': 1e-14})
        hs = np.maximum(res.x, 0.0)
        mm = hs.max()
        if mm > 0:
            hs = hs / mm
        return hs, _R_from_h(hs)
    except Exception as e:
        print("SLSQP failed:", e)
        return h, _R_from_h(h)


def _exact_lbfgsb(h, deadline):
    if time.process_time() > deadline:
        return h, _R_from_h(h)
    try:
        res = minimize(_neg_R_and_grad, h.copy(), jac=True,
                       method='L-BFGS-B',
                       bounds=[(0.0, None)] * h.size,
                       options={'maxiter': 200, 'ftol': 1e-15, 'gtol': 1e-12})
        h1 = np.maximum(res.x, 0.0)
        m = h1.max()
        if m > 0:
            h1 = h1 / m
        return h1, _R_from_h(h1)
    except Exception as e:
        print("exact failed:", e)
        return h, _R_from_h(h)


def _pair_sweep(h, deadline):
    """Powell on adjacent pairs (h_i, h_{i+1}) over the support."""
    h = h.copy()
    m = h.max()
    if m > 0:
        h = h / m
    cur_val = _R_from_h(h)
    thr = 1e-8 * h.max()
    nz = np.where(h >= thr)[0]
    if nz.size == 0:
        return h, cur_val
    lo, hi = int(nz[0]), int(nz[-1])
    for i in range(lo, hi):
        if time.process_time() > deadline:
            break
        a0 = h[i]
        b0 = h[i + 1]
        hi_a = 3.0 * a0 + 1e-9
        hi_b = 3.0 * b0 + 1e-9
        if hi_a <= 0:
            hi_a = 1e-6
        if hi_b <= 0:
            hi_b = 1e-6

        def f(v, _i=i):
            hh = h.copy()
            hh[_i] = v[0]
            hh[_i + 1] = v[1]
            return -_R_from_h(hh)

        try:
            res = minimize(f, np.array([a0, b0]), method='Powell',
                           bounds=[(0.0, hi_a), (0.0, hi_b)],
                           options={'xtol': 1e-9, 'ftol': 1e-13, 'maxiter': 200})
            if -res.fun > cur_val + 1e-13:
                h[i] = max(res.x[0], 0.0)
                h[i + 1] = max(res.x[1], 0.0)
                m = h.max()
                if m > 0:
                    h = h / m
                cur_val = _R_from_h(h)
        except Exception:
            pass
    return h, cur_val


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.7

    if start is None:
        N = 401
        centers = np.arange(N)
        s = np.exp(-0.5 * ((centers - (N - 1) / 2.0) / 50.0) ** 2)
    else:
        s = np.asarray(start, dtype=float).ravel()

    s = np.maximum(s, 0.0)
    if s.max() <= 0:
        s = np.ones_like(s)
    s = s / s.max()

    best_h = s.copy()
    best_val = _R_from_h(best_h)
    h = best_h.copy()

    for rnd in range(3):
        if time.process_time() > deadline:
            break
        hs, vs = _slsqp_round(h, deadline)
        print("round", rnd, "SLSQP score", vs)
        if vs > best_val:
            best_val = vs
            best_h = hs.copy()
        h = hs.copy()

        if time.process_time() > deadline:
            break
        h1, v1 = _exact_lbfgsb(h, deadline)
        print("round", rnd, "exact score", v1)
        if v1 > best_val:
            best_val = v1
            best_h = h1.copy()
        h = h1.copy()

        if time.process_time() > deadline:
            break
        h2, v2 = _pair_sweep(h, deadline)
        print("round", rnd, "pair sweep score", v2)
        if v2 > best_val:
            best_val = v2
            best_h = h2.copy()
        h = h2.copy()

    print("score approx", best_val)
    return best_h
